async(page)=>{
 const account=null; // Inject only the disposable setup ledger at execution time; never commit credentials.
 if(!account)throw Error('Requires the private disposable session-account fixture')
 const base='http://127.0.0.1:5173/',checks=[],check=(v,m)=>{if(!v)throw Error(m);checks.push(m)},read=p=>p.evaluate(async()=>{const m=await import('/src/services/cloud.ts'),c=await m.rpc('context'),notes=await m.rpc('announcements');return {uid:c.uid,name:c.profile?.display_name,home:c.profile?.hometown,ack:notes.find(n=>n.kind==='basic').acknowledged}})
 await page.goto(base+'?real-session-start='+Date.now()+'#/');await page.getByRole('heading',{name:/注册网页账号|登录小食云记/}).waitFor();check(true,'首次访问先进入账号流程');if(await page.getByRole('button',{name:'已有账号，去登录',exact:true}).count())await page.getByRole('button',{name:'已有账号，去登录',exact:true}).click();await page.getByRole('textbox',{name:'登录账号',exact:true}).fill(account.name);await page.getByLabel('登录密码',{exact:true}).fill(account.password);await page.getByRole('button',{name:'登录',exact:true}).click();await page.getByRole('heading',{name:'完善资料',exact:true}).waitFor();check(true,'真实密码登录后缺资料必须先完善');await page.getByRole('button',{name:'保存资料',exact:true}).click();check(await page.getByRole('heading',{name:'完善资料',exact:true}).isVisible(),'缺少必填资料不能进入主程序');check(await page.getByRole('dialog',{name:'公告',exact:true}).count()===0,'资料未完成时不会提前弹公告');await page.getByRole('textbox',{name:'昵称',exact:true}).fill('持久登录验收同学');await page.getByRole('button',{name:/家乡省市.*请选择省份/}).click();await page.getByRole('button',{name:'云南省',exact:true}).click();await page.getByRole('button',{name:'昆明市',exact:true}).click();await page.getByRole('button',{name:'确认家乡',exact:true}).click();await page.getByRole('button',{name:'保存资料',exact:true}).click();const dialog=page.getByRole('dialog',{name:'公告',exact:true});await dialog.waitFor();check((await dialog.innerText()).includes('基本使用须知'),'真实资料保存后强制基本须知');await page.keyboard.press('Escape');check(await dialog.isVisible(),'首次真实公告不能按Esc跳过');await dialog.getByRole('button',{name:/^我已知晓/}).click();await dialog.waitFor({state:'hidden'});await page.locator('.profile-heading').waitFor();check((await page.locator('.profile-heading').innerText()).includes('持久登录验收同学'),'云端昵称和省市保存后可见');let state=await read(page);check(state.home==='云南省昆明市','云端实际保存完整身份资料');check(await page.evaluate(password=>!Object.values(localStorage).some(v=>v.includes(password)),account.password),'网页本地没有保存明文密码');await page.goto('about:blank');const reopened=await page.context().newPage();try{await reopened.goto(base+'?session-reopen='+Date.now()+'#/me');await reopened.locator('.profile-heading').waitFor();state=await read(reopened);check(state.uid===account.uid,'新开独立标签自动恢复同一真实账号');check(state.name==='持久登录验收同学'&&state.home==='云南省昆明市','恢复登录后昵称省市仍在');check(state.ack,'基本须知已读由云端恢复');check(await reopened.getByRole('dialog',{name:'公告',exact:true}).count()===0,'重开不再强弹已读基本须知');await reopened.reload();await reopened.locator('.profile-heading').waitFor();check((await read(reopened)).uid===account.uid,'刷新页面无需重新输入账号密码');const refreshed=await reopened.evaluate(async()=>{const m=await import('/src/services/cloud.ts'),r=await m.cloudAuth.refreshSession();return !r.error&&!!r.data?.session});check(refreshed,'实际刷新登录令牌成功');check((await read(reopened)).uid===account.uid,'令牌刷新后身份保持不变');await reopened.getByRole('button',{name:'退出登录',exact:true}).click();await reopened.getByRole('heading',{name:'登录小食云记',exact:true}).waitFor();check(true,'主动退出后正确回到登录流程');await reopened.getByRole('textbox',{name:'登录账号',exact:true}).fill(account.name);await reopened.getByLabel('登录密码',{exact:true}).fill(account.password);await reopened.getByRole('button',{name:'登录',exact:true}).click();await reopened.locator('.profile-heading').waitFor();state=await read(reopened);check(state.name==='持久登录验收同学'&&state.home==='云南省昆明市','再次登录无需重新填写昵称头像省市');check(state.ack&&await reopened.getByRole('dialog',{name:'公告',exact:true}).count()===0,'再次登录保留已读且不强弹旧公告');await reopened.getByRole('button',{name:'退出登录',exact:true}).click();await reopened.getByRole('heading',{name:'登录小食云记',exact:true}).waitFor();return {checks,realSession:true,passwordPersisted:false,phoneWeChatTested:false}}finally{await reopened.close();await page.goto(base+'?session-clean=1#/')}
}
